1	/**
2	 * Renderer for third-party MOD BODY content — Modrinth project markdown,
3	 * Steam Workshop BBCode, Thunderstore READMEs. Deliberately separate from
4	 * lib/blog.ts's `renderMarkdown`, which stays first-party-only (blog posts,
5	 * admin docs, announcements, What's New) and keeps its simple
6	 * "escape everything, no raw HTML ever" model — that's correct for content
7	 * this repo's own authors write, but wrong here.
8	 *
9	 * WHY THIS EXISTS (2026-09-24 NxLabs description-gap fix): real Modrinth
10	 * project bodies routinely embed raw HTML inline with markdown — confirmed
11	 * live against the real API: `sodium`'s body contains literal `<center>`,
12	 * `<img>`; BepInExPack_Valheim's Thunderstore README contains `<details>`,
13	 * `<br>`. Piping that through lib/blog.ts's `esc()`-first renderer turns
14	 * every tag into visible literal text ("&lt;center&gt;This mod...&lt;/center&gt;")
15	 * instead of rendering it — exactly the bug this module fixes.
16	 *
17	 * SAFETY MODEL: every input is HTML-escaped FIRST (nothing here ever trusts
18	 * a raw `<` from an upstream source). A fixed ALLOW-LIST of simple tags is
19	 * then selectively restored by matching the ALREADY-ESCAPED text against
20	 * exact literal patterns (e.g. `&lt;center&gt;` -> `<center>`). An arbitrary
21	 * string from a mod body can never forge its way back into a real tag
22	 * unless it exactly matches one of the patterns below — attribute VALUES
23	 * (img src, a href) are extracted, validated (https-only, no javascript:/
24	 * data:), and re-emitted through a fresh, controlled template; the
25	 * attribute text itself is never echoed back verbatim. This is why this
26	 * approach is safe against injection despite rendering third-party-authored
27	 * HTML, without pulling in a new npm dependency (this repo's own convention
28	 * — see lib/blog.ts's own hand-rolled renderer, components/ui/charts.tsx's
29	 * dependency-free SVG charts).
30	 *
31	 * HEADING POLICY: every in-body heading (markdown `#`/`##`/`###`, BBCode
32	 * [h1]/[h2]/[h3]) is capped at `<h3>` — the page around this content already
33	 * has its own `<h1>` (the mod name) and `<h2>` ("Description"); a mod author
34	 * should never be able to inject a second, competing one.
35	 */
36	
37	function esc(s: string): string {
38	  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
39	}
40	
41	function escAttr(s: string): string {
42	  return esc(s).replace(/"/g, "&quot;");
43	}
44	
45	const CLS = {
46	  h3: "mt-6 mb-2 text-lg font-semibold text-white",
47	  p: "mb-4 leading-relaxed text-slate-300",
48	  ul: "mb-4 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
49	  ol: "mb-4 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
50	  li: "leading-relaxed",
51	  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
52	  img: "w-full rounded-xl border border-white/10 shadow-lg shadow-black/20 my-4",
53	  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
54	  pre: "mb-4 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
55	  blockquote: "mb-4 border-l-2 border-white/15 pl-4 italic text-slate-400",
56	  hr: "my-6 border-white/[0.08]",
57	};
58	
59	/**
60	 * Only http(s) allowed, https FORCED (audit: "force https on embedded
61	 * images"). Protocol-relative `//host/img.png` gets an https: prefix.
62	 * Anything else (data:, javascript:, blob:, bare text) is rejected — the
63	 * caller drops the element entirely rather than render a broken/unsafe one.
64	 */
65	function safeImageSrc(u: string | null | undefined): string | null {
66	  if (!u) return null;
67	  const t = u.trim();
68	  if (/^https:\/\//i.test(t)) return t;
69	  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
70	  if (/^\/\//.test(t)) return `https:${t}`;
71	  return null;
72	}
73	
74	/** Only http(s) or same-site root-relative allowed for links; else "#". */
75	function safeLinkHref(u: string | null | undefined): string {
76	  if (!u) return "#";
77	  const t = u.trim();
78	  if (/^https:\/\//i.test(t)) return t;
79	  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
80	  if (/^\//.test(t)) return t;
81	  return "#";
82	}
83	
84	function extractAttr(attrs: string, name: string): string | null {
85	  const m = attrs.match(new RegExp(`${name}\\s*=\\s*"([^"]*)"`, "i")) ?? attrs.match(new RegExp(`${name}\\s*=\\s*'([^']*)'`, "i"));
86	  return m ? m[1] : null;
87	}
88	
89	/** Simple wrap tags: no attributes ever kept, just the tag shell restored. */
90	const WRAP_TAG_MAP: Record<string, { open: string; close: string }> = {
91	  center: { open: '<div class="text-center">', close: "</div>" },
92	  details: { open: "<details>", close: "</details>" },
93	  summary: { open: '<summary class="cursor-pointer font-medium text-white">', close: "</summary>" },
94	  sub: { open: "<sub>", close: "</sub>" },
95	  sup: { open: "<sup>", close: "</sup>" },
96	  small: { open: '<span class="text-xs">', close: "</span>" },
97	  b: { open: "<strong class=\"font-semibold text-white\">", close: "</strong>" },
98	  strong: { open: "<strong class=\"font-semibold text-white\">", close: "</strong>" },
99	  i: { open: "<em>", close: "</em>" },
100	  em: { open: "<em>", close: "</em>" },
101	  u: { open: "<u>", close: "</u>" },
102	  s: { open: "<s>", close: "</s>" },
103	  strike: { open: "<s>", close: "</s>" },
104	  code: { open: `<code class="${CLS.code}">`, close: "</code>" },
105	  blockquote: { open: `<blockquote class="${CLS.blockquote}">`, close: "</blockquote>" },
106	  // Block-level structural tags — real Modrinth bodies routinely use these
107	  // directly as raw HTML instead of markdown syntax (confirmed live:
108	  // bookshelf-lib's whole body is <p>/<h3>/<ul>/<li>, not "# " / "- ").
109	  // h1-h6 are handled separately below (all collapse to h3 — HEADING POLICY).
110	  p: { open: `<p class="${CLS.p}">`, close: "</p>" },
111	  ul: { open: `<ul class="${CLS.ul}">`, close: "</ul>" },
112	  ol: { open: `<ol class="${CLS.ol}">`, close: "</ol>" },
113	  li: { open: `<li class="${CLS.li}">`, close: "</li>" },
114	  div: { open: "<div>", close: "</div>" },
115	};
116	const VOID_TAGS = new Set(["br", "hr"]);
117	/** Tags whose OPENING form means "this whole paragraph run IS a raw HTML
118	 *  block, don't ALSO wrap it in our own <p>" — see renderModMarkdown's
119	 *  paragraph branch. Kept in sync with WRAP_TAG_MAP + the heading regex. */
120	const BLOCK_STARTER_RE = /^<(p|div|h[1-6]|ul|ol|li|center|details|blockquote)[\s>]/i;
121	
122	/**
123	 * Restore a fixed allow-list of safe tags from ALREADY-ESCAPED text (see
124	 * file header for why this order is what makes it safe). Handles simple
125	 * wrap tags, void tags (br/hr), and the two attribute-carrying tags
126	 * (img/a) via strict extraction + revalidation, never verbatim echo.
127	 */
128	function restoreSafeHtml(escaped: string): string {
129	  let s = escaped;
130	
131	  // Void tags: &lt;br&gt; / &lt;br/&gt; / &lt;br /&gt; / &lt;hr ...&gt;
132	  s = s.replace(/&lt;(br|hr)\s*\/?\s*&gt;/gi, (_m, tag: string) => `<${tag.toLowerCase()} />`);
133	
134	  // img — attribute-carrying, strictly re-templated.
135	  s = s.replace(/&lt;img\s+([^&]*?)\/?\s*&gt;/gi, (_m, attrs: string) => {
136	    const src = safeImageSrc(extractAttr(attrs, "src"));
137	    if (!src) return "";
138	    const alt = extractAttr(attrs, "alt") ?? "";
139	    return `<img src="${escAttr(src)}" alt="${escAttr(alt)}" loading="lazy" class="${CLS.img}" />`;
140	  });
141	
142	  // a — attribute-carrying, strictly re-templated. Opening + closing handled separately.
143	  s = s.replace(/&lt;a\s+([^&]*?)&gt;/gi, (_m, attrs: string) => {
144	    const href = safeLinkHref(extractAttr(attrs, "href"));
145	    const external = href.startsWith("http");
146	    return `<a class="${CLS.a}" href="${escAttr(href)}"${external ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>`;
147	  });
148	  s = s.replace(/&lt;\/a&gt;/gi, "</a>");
149	
150	  // Raw HTML headings — ALL levels collapse to h3, matching the markdown
151	  // heading policy above (a mod author's own <h1>/<h2> never outranks the
152	  // page's real h1/h2). Handled separately from WRAP_TAG_MAP because every
153	  // level maps to the SAME output tag, not tag-name-preserving.
154	  s = s.replace(/&lt;h[1-6](?:\s[^&]*?)?&gt;/gi, `<h3 class="${CLS.h3}">`);
155	  s = s.replace(/&lt;\/h[1-6]\s*&gt;/gi, "</h3>");
156	
157	  // Simple wrap tags (open + close), no attributes ever kept.
158	  for (const [tag, { open, close }] of Object.entries(WRAP_TAG_MAP)) {
159	    s = s.replace(new RegExp(`&lt;${tag}(?:\\s[^&]*?)?&gt;`, "gi"), open);
160	    s = s.replace(new RegExp(`&lt;/${tag}\\s*&gt;`, "gi"), close);
161	  }
162	
163	  return s;
164	}
165	
166	// Private-use sentinels protecting inline code spans from further processing.
167	const S0 = "";
168	const S1 = "";
169	
170	function inlineMd(text: string): string {
171	  const codes: string[] = [];
172	  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
173	    codes.push(c);
174	    return `${S0}${codes.length - 1}${S1}`;
175	  });
176	  s = restoreSafeHtml(s);
177	  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
178	  s = s.replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, "<em>$1</em>");
179	  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_m, alt: string, u: string) => {
180	    const safe = safeImageSrc(u);
181	    if (!safe) return "";
182	    return `<img class="${CLS.img}" src="${safe}" alt="${escAttr(alt)}" loading="lazy" />`;
183	  });
184	  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
185	    const safe = safeLinkHref(u);
186	    const ext = safe.startsWith("http");
187	    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${t}</a>`;
188	  });
189	  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
190	  return s;
191	}
192	
193	/**
194	 * Cut raw markdown SOURCE at a real paragraph/line boundary at or before
195	 * `maxChars`, never mid-word/mid-tag — replaces the old
196	 * `longDescription.slice(0, 6000)` raw character slice, which could (and,
197	 * on real bodies, did) cut in the middle of a markdown construct or a raw
198	 * HTML tag. Returns the untruncated text unchanged when it already fits.
199	 */
200	export function truncateMarkdown(md: string, maxChars = 6000): { text: string; truncated: boolean } {
201	  if (md.length <= maxChars) return { text: md, truncated: false };
202	  const window = md.slice(0, maxChars);
203	  const paraBreak = window.lastIndexOf("\n\n");
204	  const lineBreak = window.lastIndexOf("\n");
205	  const spaceBreak = window.lastIndexOf(" ");
206	  const cut = paraBreak > maxChars * 0.5 ? paraBreak : lineBreak > maxChars * 0.5 ? lineBreak : spaceBreak > 0 ? spaceBreak : maxChars;
207	  return { text: md.slice(0, cut).trimEnd(), truncated: true };
208	}
209	
210	/** Real Markdown (Modrinth project body / Thunderstore README) -> sanitized HTML. */
211	export function renderModMarkdown(md: string): string {
212	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
213	  const out: string[] = [];
214	  let i = 0;
215	
216	  while (i < lines.length) {
217	    const line = lines[i];
218	    if (!line.trim()) { i++; continue; }
219	
220	    if (/^---+$/.test(line.trim())) { out.push(`<hr class="${CLS.hr}" />`); i++; continue; }
221	
222	    // Fenced code block — contents escaped, never markdown/HTML processed.
223	    if (/^```/.test(line.trim())) {
224	      const buf: string[] = [];
225	      i++;
226	      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
227	      i++;
228	      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
229	      continue;
230	    }
231	
232	    // Standalone image line -> figure.
233	    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
234	    if (img) {
235	      const safe = safeImageSrc(img[2]);
236	      if (safe) {
237	        out.push(`<img class="${CLS.img}" src="${safe}" alt="${escAttr(img[1])}" loading="lazy" />`);
238	        i++;
239	        continue;
240	      }
241	    }
242	
243	    // Headings — ALL capped at h3 (see file header "HEADING POLICY").
244	    if (/^#{1,6}\s+/.test(line)) {
245	      out.push(`<h3 class="${CLS.h3}">${inlineMd(line.replace(/^#{1,6}\s+/, ""))}</h3>`);
246	      i++;
247	      continue;
248	    }
249	
250	    // Ordered list.
251	    if (/^\s*\d+\.\s+/.test(line)) {
252	      const items: string[] = [];
253	      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) { items.push(lines[i].replace(/^\s*\d+\.\s+/, "")); i++; }
254	      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inlineMd(t)}</li>`).join("")}</ol>`);
255	      continue;
256	    }
257	
258	    // Unordered list.
259	    if (/^\s*[-*]\s+/.test(line)) {
260	      const items: string[] = [];
261	      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) { items.push(lines[i].replace(/^\s*[-*]\s+/, "")); i++; }
262	      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inlineMd(t)}</li>`).join("")}</ul>`);
263	      continue;
264	    }
265	
266	    // Paragraph — gather consecutive non-blank, non-block-start lines. This
267	    // is also what lets a real multi-line raw HTML block (e.g. Thunderstore
268	    // READMEs' `<details>\n<summary>...</summary>\ntext\n</details>`) join
269	    // into one text run that restoreSafeHtml() processes as a whole.
270	    const para = [line];
271	    i++;
272	    while (
273	      i < lines.length && lines[i].trim() &&
274	      !/^#{1,6}\s/.test(lines[i]) && !/^\s*[-*]\s+/.test(lines[i]) && !/^\s*\d+\.\s+/.test(lines[i]) &&
275	      !/^```/.test(lines[i].trim()) && !/^---+$/.test(lines[i].trim())
276	    ) { para.push(lines[i]); i++; }
277	    const joined = para.join(" ").trim();
278	    // A run that's ITSELF a raw HTML block (real Modrinth bodies routinely
279	    // use <p>/<h3>/<ul>/<li> directly instead of markdown syntax — confirmed
280	    // live) gets rendered as-is rather than double-wrapped in our own <p>,
281	    // which would nest a restored <p> inside this function's <p> (invalid
282	    // HTML the browser would silently un-nest, breaking the structure).
283	    if (BLOCK_STARTER_RE.test(joined)) {
284	      out.push(inlineMd(joined));
285	    } else {
286	      out.push(`<p class="${CLS.p}">${inlineMd(joined)}</p>`);
287	    }
288	  }
289	
290	  return out.join("\n");
291	}
292	
293	/**
294	 * Steam Workshop's `file_description` — real BBCode, not markdown (verified
295	 * live: `[h1][b]I DID NOT CREATE THIS MAP![/b][/h1]`). Square brackets are
296	 * not HTML-meaningful, so `esc()` leaves BBCode tags untouched, letting the
297	 * same escape-first/allow-list-restore approach apply here too.
298	 */
299	export function renderBBCode(bbcode: string): string {
300	  const escaped = esc(bbcode ?? "");
301	  const lines = escaped.replace(/\r\n/g, "\n").split("\n");
302	  const out: string[] = [];
303	  let i = 0;
304	
305	  const inlineBB = (text: string): string => {
306	    let s = text;
307	    s = s.replace(/\[b\]([\s\S]*?)\[\/b\]/gi, '<strong class="font-semibold text-white">$1</strong>');
308	    s = s.replace(/\[i\]([\s\S]*?)\[\/i\]/gi, "<em>$1</em>");
309	    s = s.replace(/\[u\]([\s\S]*?)\[\/u\]/gi, "<u>$1</u>");
310	    s = s.replace(/\[(?:strike|s)\]([\s\S]*?)\[\/(?:strike|s)\]/gi, "<s>$1</s>");
311	    s = s.replace(/\[url=([^\]]+)\]([\s\S]*?)\[\/url\]/gi, (_m, href: string, t: string) => {
312	      const safe = safeLinkHref(href);
313	      const ext = safe.startsWith("http");
314	      return `<a class="${CLS.a}" href="${escAttr(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${t}</a>`;
315	    });
316	    s = s.replace(/\[url\]([\s\S]*?)\[\/url\]/gi, (_m, href: string) => {
317	      const safe = safeLinkHref(href);
318	      const ext = safe.startsWith("http");
319	      return `<a class="${CLS.a}" href="${escAttr(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${href}</a>`;
320	    });
321	    s = s.replace(/\[img\]([\s\S]*?)\[\/img\]/gi, (_m, src: string) => {
322	      const safe = safeImageSrc(src.trim());
323	      return safe ? `<img class="${CLS.img}" src="${safe}" alt="" loading="lazy" />` : "";
324	    });
325	    return s;
326	  };
327	
328	  while (i < lines.length) {
329	    const line = lines[i];
330	    if (!line.trim()) { i++; continue; }
331	
332	    // Headings — capped at h3, same policy as the markdown renderer.
333	    const h = line.trim().match(/^\[h[1-3]\]([\s\S]*?)\[\/h[1-3]\]\s*$/i);
334	    if (h) { out.push(`<h3 class="${CLS.h3}">${inlineBB(h[1])}</h3>`); i++; continue; }
335	
336	    // [code]...[/code] — may span lines; contents left escaped, not BBCode-processed.
337	    if (/^\[code\]/i.test(line.trim())) {
338	      const buf: string[] = [line.replace(/^\[code\]/i, "")];
339	      i++;
340	      while (i < lines.length && !/\[\/code\]/i.test(lines[i])) { buf.push(lines[i]); i++; }
341	      if (i < lines.length) { buf.push(lines[i].replace(/\[\/code\].*$/i, "")); i++; }
342	      out.push(`<pre class="${CLS.pre}"><code>${buf.join("\n")}</code></pre>`);
343	      continue;
344	    }
345	
346	    // [list]...[/list] with [*] items (Steam's BBCode list, no closing [/*]).
347	    if (/^\[list\]/i.test(line.trim())) {
348	      const items: string[] = [];
349	      i++;
350	      while (i < lines.length && !/^\[\/list\]/i.test(lines[i].trim())) {
351	        const t = lines[i].trim().replace(/^\[\*\]\s*/, "");
352	        if (t) items.push(t);
353	        i++;
354	      }
355	      if (i < lines.length) i++; // consume [/list]
356	      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inlineBB(t)}</li>`).join("")}</ul>`);
357	      continue;
358	    }
359	
360	    if (/^\[quote/i.test(line.trim())) {
361	      const buf: string[] = [];
362	      const firstLineContent = line.replace(/^\[quote(?:=[^\]]*)?\]/i, "");
363	      if (firstLineContent.trim()) buf.push(firstLineContent);
364	      i++;
365	      while (i < lines.length && !/\[\/quote\]/i.test(lines[i])) { buf.push(lines[i]); i++; }
366	      if (i < lines.length) { const rest = lines[i].replace(/\[\/quote\].*$/i, ""); if (rest.trim()) buf.push(rest); i++; }
367	      out.push(`<blockquote class="${CLS.blockquote}">${inlineBB(buf.join(" "))}</blockquote>`);
368	      continue;
369	    }
370	
371	    // Paragraph — gather until blank line.
372	    const para = [line];
373	    i++;
374	    while (i < lines.length && lines[i].trim() && !/^\[(?:h[1-3]|code|list|quote)/i.test(lines[i].trim())) { para.push(lines[i]); i++; }
375	    out.push(`<p class="${CLS.p}">${inlineBB(para.join(" "))}</p>`);
376	  }
377	
378	  return out.join("\n");
379	}
380	
381	export type ModBodySource = "modrinth" | "thunderstore" | "steam_workshop" | "other";
382	
383	/**
384	 * Single entry point the two mod-detail pages call. Truncates the RAW
385	 * source at a real boundary first (never a mid-tag character slice), then
386	 * renders through the format-appropriate renderer.
387	 */
388	export function renderModBody(rawBody: string, source: ModBodySource, maxChars = 6000): { html: string; truncated: boolean } {
389	  const { text, truncated } = truncateMarkdown(rawBody, maxChars);
390	  const html = source === "steam_workshop" ? renderBBCode(text) : renderModMarkdown(text);
391	  return { html, truncated };
392	}
393

  // higher base image opacity, and a visibly lighter scrim — verified live
  // afterward on both CS2 and Rust (this same fallback path), plus Valheim
  // and Palworld mods that hit the OTHER branch (their own icon/screenshot,
  // blurred) to confirm that path still renders correctly too.
  const familyHeroSlug = GAME_ART_SLUG[mod.gameFamily as GameFamily]?.hero;
  const ownHeroImage = mod.galleryUrls[0] ?? mod.iconUrl ?? null;
  const heroImage = ownHeroImage ?? (familyHeroSlug ? `/games/art/${familyHeroSlug}_hero.jpg` : null);
  const heroIsGameArt = !ownHeroImage && !!heroImage;
  // Rendered through lib/mod-markdown.ts, NOT lib/blog.ts's renderMarkdown —
  // see the public /mods/[family]/[slug] page's identical comment. Real
  // third-party HTML (Modrinth bodies, Thunderstore READMEs) needs to
  // actually render, not show up as literal escaped tag text.
  const longDescription = mod.longDescription
    ? renderModBody(mod.longDescription, mod.source as ModBodySource, 6000)
    : null;
  const longDescriptionHtml = longDescription?.html ?? null;

  return (
    <PageShell
      eyebrow="NxLabs"
      title={mod.name}
----
          </div>

          {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}

          {longDescriptionHtml && (
